return {
  user_id: $json.user_id,
  input: $json.input,
  state: $json.state
};

// ─────────────────────────────────────────
// PARTIR DEL ESTADO ANTERIOR
// ─────────────────────────────────────────
const state = { ...$json.state };

// Asegurar estructura mínima
state.support = typeof state.support === "number" ? state.support : 0;
state.resources = typeof state.resources === "number" ? state.resources : 0;
state.risk = typeof state.risk === "number" ? state.risk : 0;
state.location = typeof state.location === "string" ? state.location : "desconocido";
state.summary = typeof state.summary === "string" ? state.summary : "";

// ─────────────────────────────────────────
// APLICAR CAMBIOS DEL TURNO
// ─────────────────────────────────────────
const changes = $json.ai_result?.state_changes || {};

// Cambios estratégicos (balanceados)
if (typeof changes.support === "number") {
  state.support += changes.support;
}

if (typeof changes.resources === "number") {
  state.resources += changes.resources;
}

if (typeof changes.risk === "number") {
  state.risk += changes.risk;
}

// Cambio de localización
if (typeof changes.location === "string" && changes.location.length > 0) {
  state.location = changes.location;
}

// ─────────────────────────────────────────
// AVANCE DE ESCENA (SOLO TRAS ELECCIÓN REAL)
// ─────────────────────────────────────────
if (state.phase === "prologue") {
  const scenes = $json.scenes;
  const currentScene = scenes[state.scene_id];

  if (!currentScene) {
    throw new Error(`Escena desconocida: ${state.scene_id}`);
  }

  // ✅ Si aún NO se ha presentado la escena,
  // solo la marcamos como presentada
  if (!state.scene_presented) {
    state.scene_presented = true;
  }
  // ✅ Si ya se presentó, ahora sí avanzamos
  else {
    if (currentScene.next === "game_start") {
      state.phase = "game";
      delete state.scene_id;
      delete state.scene_presented;
    } else {
      state.scene_id = currentScene.next;
      state.scene_presented = false;
    }
  }
}
// ─────────────────────────────────────────
// VISUAL (INTENCIÓN, NO GENERACIÓN)
// ─────────────────────────────────────────
if ($json.ai_result.visual?.request === true) {
  state.pending_visual = {
    prompt: $json.ai_result.visual.prompt,
    reason: $json.ai_result.visual.reason
  };
}

// ─────────────────────────────────────────
// VOZ (INTENCIÓN, NO GENERACIÓN)
// ─────────────────────────────────────────
if ($json.ai_result.voice?.request === true) {
  state.pending_voice = {
    text: $json.ai_result.voice.text,
    voice_id: $json.ai_result.voice.voice_id
  };
}

// ─────────────────────────────────────────
// RESUMEN NARRATIVO
// ─────────────────────────────────────────
if (typeof $json.ai_result?.new_summary === "string") {
  state.summary = $json.ai_result.new_summary;
}

// ─────────────────────────────────────────
// DEVOLVER RESULTADO COMPLETO
// ─────────────────────────────────────────
return {
  ...$json,
  state,
  narrative: $json.ai_result.narrative,
  options: $json.ai_result.options
};

let content = $json.choices?.[0]?.message?.content;

try {
  const parsed = JSON.parse(content);

  return [{
    json: {
      ...$json,
      ai_result: parsed
    }
  }];

} catch (e) {
  return [{
    json: {
      ...$json,
      ai_result: {
        narrative: "Algo salió mal. El sistema no pudo interpretar la respuesta.",
        options: ["Esperar", "Reintentar", "Retirarse"],
        state_changes: {},
        new_summary: $json.state.summary
      },
      error: "Invalid JSON from AI"
    }
  }];
}

return [
  {
    json: {
      body: {
        model: "gpt-4o-mini",
        messages: [
          {
            role: "user",
            content: $json.prompt
          }
        ],
        temperature: 0.8
      }
    }
  }
];

const staticData = $getWorkflowStaticData("global");

// Guardar estado actualizado
staticData[$json.user_id] = $json.state;

return [{
  json: $json
}];

const userId = $json.body?.user_id || "default";
const staticData = $getWorkflowStaticData("global");

// ─────────────────────────────────────────
// CREAR ESTADO NUEVO (SI NO EXISTE)
// ─────────────────────────────────────────
if (!staticData[userId]) {
  staticData[userId] = {
    // Control de fase
    phase: "prologue",
    scene_id: "prologue_1",
    scene_presented: false,

    // Estado estratégico
    location: "Colonia Britannia – Distrito Central",
    support: 5,
    resources: 3,
    risk: 10,

    // Narrativa
    summary: "Eres un estudiante imperial que observa el mundo desde la distancia.",

    // Multimedia
    current_image: null,
    current_voice: null
  };
}

// ─────────────────────────────────────────
// DEVOLVER ESTADO
// ─────────────────────────────────────────
return [{
  json: {
    user_id: userId,
    input: $json.body?.input || "",
    state: { ...staticData[userId] }
  }
}];

return [{
  json: {
    ...$json,
    use_mock: true // ← cambia a false cuando quieras OpenAI real
  }
}];

const state = $json.state;
const scenes = $json.scenes;

const scene = scenes[state.scene_id];

if (!scene) {
  throw new Error(`Mock: escena desconocida ${state.scene_id}`);
}

let narrative = "";
let options = [];
let state_changes = { support: 0, resources: 0, risk: 0, location: state.location };
let new_summary = state.summary;
let visual = { request: false, reason: "", prompt: "" };
let voice = { request: false, text: "", voice_id: "narrator_default" };

// ─────────────────────────────────────────
// PROLOGUE 1
// ─────────────────────────────────────────
if (scene.id === "prologue_1") {
  narrative = `
Estudias en una universidad imperial porque es la única opción viable.
No por convicción. No por lealtad.

Desde lo alto del distrito central, la ciudad parece estable.
Los guetos quedan lejos. La vigilancia es discreta.

La explosión rompe esa ilusión.

En los días siguientes, la represión cae sobre los barrios no imperiales.
Reconoces una furgoneta utilizada en el atentado.

Dejas un walkie‑talkie sobre el capó.

Horas después, el dispositivo emite un ruido seco.

—¿Quién eres?
`;

  options = [
    "Responder con franqueza y declarar tus intenciones",
    "Responder con cautela, ocultando parte de tu información",
    "Responder evasivamente, diciendo que contactarás más adelante"
  ];

  new_summary = "Has establecido un primer contacto con una célula insurgente.";

  visual = {
    request: true,
    reason: "Inicio del conflicto",
    prompt: "futuristic imperial city at night, distant explosion smoke, surveillance drones, tense atmosphere"
  };

  voice = {
    request: true,
    text: "La ciudad se rompe ante tus ojos. Responder es cruzar un umbral del que no hay retorno.",
    voice_id: "narrator_default"
  };
}

// ─────────────────────────────────────────
// PROLOGUE 2
// ─────────────────────────────────────────
else if (scene.id === "prologue_2") {
  narrative = `
La voz al otro lado no confía en ti.
No debería.

No preguntan por ideales.
Preguntan por información.

Qué sabes.
A quién ves.
Qué rutas observas.

No te piden que dispares.
Te piden que pienses.
`;

  options = [
    "Compartir información limitada para demostrar acceso",
    "Exagerar tu alcance para ganar peso estratégico",
    "Pedir tiempo y observar movimientos imperiales"
  ];

  state_changes = { support: 1, resources: 1, risk: 2, location: state.location };
  new_summary = "La célula empieza a medir tu valor como estratega.";

  voice = {
    request: true,
    text: "No buscan ideales. Buscan a alguien que vea el tablero completo.",
    voice_id: "narrator_default"
  };
}

// ─────────────────────────────────────────
// PROLOGUE 3
// ─────────────────────────────────────────
else if (scene.id === "prologue_3") {
  narrative = `
La redada ocurre.

No como lo dirán los informes oficiales.
Algunos logran escapar.
Otros no.

Britannia refuerza su presencia.

La célula ya no te ve como un contacto.
Te ve como un recurso.
`;

  options = [
    "Asumir un rol más activo en la coordinación",
    "Mantenerte en la sombra y analizar",
    "Centrarte en proteger a los civiles"
  ];

  state_changes = { support: 2, resources: 1, risk: 3, location: state.location };
  new_summary = "Te has convertido en parte activa de la insurgencia.";

  visual = {
    request: true,
    reason: "Cierre del prólogo",
    prompt: "military checkpoint at dawn, civilians watched by soldiers, oppressive atmosphere"
  };

  voice = {
    request: true,
    text: "El prólogo termina. El juego real comienza ahora.",
    voice_id: "narrator_default"
  };
}

// ─────────────────────────────────────────
// DEVOLVER RESPUESTA
// ─────────────────────────────────────────
return {
  ...$json,
  choices: [
    {
      message: {
        content: JSON.stringify({
          narrative,
          options,
          state_changes,
          new_summary,
          visual,
          voice
        })
      }
    }
  ]
};

const imageBase64 = $json.images[0];

return {
  ...$json,
  image: `data:image/png;base64,${imageBase64}`
};

const state = { ...$json.state };
delete state.pending_visual;

return {
  ...$json,
  state
};

const imageUrl = "/images/scenes/placeholder.jpeg";

return {
  ...$json,
  image: imageUrl,
  state: {
    ...$json.state,
    current_image: imageUrl
  }
};

// Si NO hay image en la respuesta,
// pero SÍ hay una imagen guardada en el estado,
// la reinyectamos.

if (!$json.image && $json.state?.current_image) {
  return {
    ...$json,
    image: $json.state.current_image
  };
}

// Si ya hay image (evento visual nuevo), no tocamos nada
return {
  ...$json
};

return {
  ...$json,
  voice_url: "/audio/voice/narrator_placeholder.mp3",
  state: {
    ...$json.state,
    current_voice: "/audio/voice/narrator_placeholder.mp3"
  }
};

const state = { ...$json.state };
delete state.pending_voice;

return {
  ...$json,
  state
};

if (!$json.voice_url && $json.state?.current_voice) {
  return {
    ...$json,
    voice_url: $json.state.current_voice
  };
}

return { ...$json };

/**
 * generateVoice
 * ----------------
 * Nodo preparado para TTS real (Piper / Coqui).
 * Actualmente puede fallar si el servicio no está activo,
 * pero la arquitectura queda lista.
 */

const pending = $json.state.pending_voice;

if (!pending || !pending.text) {
  // No debería pasar porque hay un IF antes,
  // pero por seguridad:
  return { ...$json };
}

// 🔹 CONFIGURACIÓN DEL SERVICIO TTS
const TTS_ENDPOINT = "http://localhost:5001/tts";

// 🔹 Payload para el motor de voz
const payload = {
  text: pending.text,
  voice_id: pending.voice_id || "narrator_default"
};

/**
 * En un Code node NO podemos hacer fetch directamente,
 * así que este nodo representa la preparación del request.
 *
 * La llamada real se hará con un HTTP Request node
 * conectado después de este.
 */

// Dejamos preparado el cuerpo para el HTTP Request
return {
  ...$json,
  tts_request: payload,
  tts_endpoint: TTS_ENDPOINT
};

const voiceUrl = $json.url;

return {
  ...$json,
  voice_url: voiceUrl,
  state: {
    ...$json.state,
    current_voice: voiceUrl
  }
};

const state = $json.state;
const scenes = $json.scenes;

const scene = scenes[state.scene_id];

let prompt = `
Eres el motor narrativo de un RPG político–estratégico.

Escena actual:
${scene.description}

Contexto del mundo:
- Sacro Imperio de Britannia
- Colonia imperial con represión creciente

Intenciones de esta escena:
${scene.intent.join(", ")}

Reglas:
- Mantén la historia coherente
- No resuelvas el conflicto global
- Genera decisiones balanceadas
- No cierres la historia

Genera narrativa y EXACTAMENTE 3 opciones
que reflejen estas intenciones.

Formato de salida JSON ya definido.
`;

return {
  ...$json,
  prompt
};

const userId = $json.body?.user_id;

if (!userId) {
  return {
    success: false,
    error: "user_id requerido"
  };
}

const staticData = $getWorkflowStaticData("global");

// ✅ BORRADO TOTAL DEL USUARIO
if (staticData[userId]) {
  delete staticData[userId];
}

return {
  success: true,
  message: `Usuario '${userId}' eliminado completamente`
};

const staticData = $getWorkflowStaticData("global");

Object.keys(staticData).forEach(key => {
  delete staticData[key];
});

return {
  success: true,
  message: "Todos los estados eliminados"
};

const PROLOGUE_SCENES = {
  prologue_1: {
    id: "prologue_1",
    description: "Primer contacto tras el atentado",
    intent: ["franqueza", "cautela", "evasión"],
    visual: true,
    voice: true,
    next: "prologue_2"
  },

  prologue_2: {
    id: "prologue_2",
    description: "Prueba de información",
    intent: ["informar", "mentir", "observar"],
    visual: false,
    voice: true,
    next: "prologue_3"
  },

  prologue_3: {
    id: "prologue_3",
    description: "Primera consecuencia real",
    intent: ["coordinar", "proteger", "analizar"],
    visual: true,
    voice: true,
    next: "game_start"
  }
};

return {
  ...$json,
  scenes: PROLOGUE_SCENES
};
